658	      // 'claude'⊂'claude-api' 类误报的根源。改为完整 trigger + 词边界匹配（保留空格的小写原文）；
659	      // CJK/混合 trigger 维持子串逻辑（中文无词边界，滑窗是刻意设计）。
660	      if (/^[a-z0-9 ._-]+$/i.test(trigger)) {
661	        const esc = trigger.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
662	        if (new RegExp(`(^|[^a-z0-9])${esc}([^a-z0-9]|$)`).test(promptLower)) {
663	          score += Math.min(t.length, 6);
