665	        }
666	        continue;
667	      }
668	      let bestLen = 0;
669	      for (let len = Math.min(t.length, 6); len >= 3; len--) {
670	        for (let i = 0; i <= t.length - len; i++) {
671	          const sub = t.slice(i, i + len);
