12	// Accept the static preview renderer's RGB/RGBA PNGs. Reject text chunks and
13	// trailing documents instead of shipping source code inside a nominal image.
14	function checkPng(png) {
15	  const reject = () => fail('PNG_REQUIRED', 'Attach complete static RGB/RGBA PNG bytes, not a path, source HTML or active document');
16	  if (!Buffer.isBuffer(png) || png.length < 45 || !png.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))) reject();
17	  let offset = 8;
18	  let width, height, channels, ended = false;
19	  const compressed = [];
20	  while (offset < png.length) {
21	    if (offset + 12 > png.length) reject();
22	    const size = png.readUInt32BE(offset), end = offset + size + 12;
23	    const type = png.toString('ascii', offset + 4, offset + 8);
24	    if (end > png.length || !['IHDR', 'IDAT', 'IEND', 'sRGB', 'gAMA', 'cHRM', 'pHYs'].includes(type) || crc32(png.subarray(offset + 4, end - 4)) !== png.readUInt32BE(end - 4)) reject();
25	    if (offset === 8 && type !== 'IHDR') reject();
26	    if (type === 'IHDR') {
27	      if (offset !== 8 || size !== 13 || png[offset + 16] !== 8 || ![2, 6].includes(png[offset + 17]) || png[offset + 18] !== 0 || png[offset + 19] !== 0 || png[offset + 20] !== 0) reject();
