29	      if (!width || !height || (width * channels + 1) * height > 128 * 1024 * 1024) reject();
30	    }
31	    if (type === 'IDAT') compressed.push(png.subarray(offset + 8, end - 4));
32	    if (type === 'IEND') { if (size !== 0 || end !== png.length) reject(); ended = true; }
33	    offset = end;
34	  }
35	  if (!ended || compressed.length === 0) reject();
36	  let pixels;
37	  try { pixels = inflateSync(Buffer.concat(compressed), { maxOutputLength: (width * channels + 1) * height }); } catch { reject(); }
38	  if (pixels.length !== (width * channels + 1) * height) reject();
39	  for (let row = 0; row < height; row++) if (pixels[row * (width * channels + 1)] > 4) reject();
40	}
